// Segment table entry: where the segment starts and how large it is
struct SegmentEntry {
    unsigned int base;   // starting physical address of this segment
    unsigned int limit;  // size of this segment in bytes
};

struct SegmentEntry segmentTable[4]; // one entry per segment

// A logical address is a segment number plus an offset inside that segment
unsigned int translate(int segmentNumber, unsigned int offset) {
    struct SegmentEntry entry = segmentTable[segmentNumber];

    if (offset >= entry.limit) {
        // offset falls outside this segment, this is an illegal access
        trapSegmentationFault(segmentNumber, offset);
    }

    unsigned int physicalAddress = entry.base + offset;
    return physicalAddress;
}

